#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/grype/tasks/code-sec-grype.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Scan the dependencies with grype"
# MISE tools={uv="latest", python="3.14"}

# USAGE flag "--debug" help="emit debug logs"
# USAGE flag "--staged" help="do nothing: grype has no staged mode"

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def submodules(root):
  """The path of each submodule of root, nested ones included."""
  try:
    result = subprocess.run(
      ["git", "-C", root, "submodule", "--quiet", "foreach", "--recursive", "echo $displaypath"],
      stdout=subprocess.PIPE,
      stderr=subprocess.DEVNULL,
      text=True,
      check=False,
    )
  except OSError:
    return []
  return [line for line in result.stdout.split("\n") if line]


def main():
  # grype reads the lockfiles of the whole tree, so it belongs to the full run
  # and to CI, not to each commit.
  if os.environ.get("usage_staged", "false") == "true":
    return 0

  root = os.environ["MISE_PROJECT_ROOT"]
  # A git submodule is a separate repository with its own `code:sec`. Thus grype
  # skips each submodule here, nested ones included.
  excludes = []
  for submodule in submodules(root):
    excludes += ["--exclude", f"./{submodule}/**"]

  helpers.print_subheader("Scanning the dependencies with grype ...")
  flags = ["-vv"] if os.environ.get("usage_debug", "false") == "true" else []
  result = helpers.tool("grype", ".", "--config", ".config/grype.yaml", "--name", root, *excludes, *flags)
  return result.returncode


if __name__ == "__main__":
  sys.exit(main())
